create table if not exists public.schedule_slots (
  id uuid primary key default gen_random_uuid(),
  resource_id uuid not null,
  slot_date date not null,
  slot_start time not null,
  slot_end time not null,
  slot_unit_minutes integer not null default 15,
  slot_group_id uuid,
  status text not null default 'free',
  linked_wizyta_id uuid,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists schedule_slots_resource_date_status_idx on public.schedule_slots (resource_id, slot_date, status);
create index if not exists schedule_slots_linked_wizyta_idx on public.schedule_slots (linked_wizyta_id);
create or replace function public.update_schedule_slots_updated_at()
returns trigger as $$
begin
  new.updated_at = now();
  return new;
end;
$$ language plpgsql;
drop trigger if exists trigger_update_schedule_slots on public.schedule_slots;
create trigger trigger_update_schedule_slots
before update on public.schedule_slots
for each row execute function public.update_schedule_slots_updated_at();
alter table public.schedule_slots enable row level security;
grant all on table public.schedule_slots to service_role;
grant select on table public.schedule_slots to authenticated;
drop policy if exists "Service role full access to schedule slots" on public.schedule_slots;
create policy "Service role full access to schedule slots"
on public.schedule_slots
for all
to service_role
using (true)
with check (true);
drop policy if exists "Authenticated read schedule slots" on public.schedule_slots;
create policy "Authenticated read schedule slots"
on public.schedule_slots
for select
to authenticated
using (true);
